package in.ac.rtu.medicare.dao;
import in.ac.rtu.medicare.config.Database; import in.ac.rtu.medicare.model.*; import java.sql.*; import java.util.*;
public class UserDao {
 public Optional<User> findByEmail(String email)throws SQLException {String q="SELECT * FROM users WHERE email=?";try(Connection c=Database.connection();PreparedStatement s=c.prepareStatement(q)){s.setString(1,email);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}}
 public Optional<User> findById(long id)throws SQLException {try(Connection c=Database.connection();PreparedStatement s=c.prepareStatement("SELECT * FROM users WHERE id=?")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}}
 public long createPatient(String name,String email,String hash,String phone)throws SQLException {try(Connection c=Database.connection()){c.setAutoCommit(false);try(PreparedStatement u=c.prepareStatement("INSERT INTO users(full_name,email,password_hash,role,phone) VALUES(?,?,?,'PATIENT',?)",Statement.RETURN_GENERATED_KEYS)){u.setString(1,name);u.setString(2,email);u.setString(3,hash);u.setString(4,phone);u.executeUpdate();try(ResultSet k=u.getGeneratedKeys()){k.next();long id=k.getLong(1);try(PreparedStatement p=c.prepareStatement("INSERT INTO patients(user_id) VALUES(?)")){p.setLong(1,id);p.executeUpdate();}c.commit();return id;}}catch(SQLException e){c.rollback();throw e;}}}
 public List<User> list()throws SQLException {List<User>x=new ArrayList<>();try(Connection c=Database.connection();PreparedStatement s=c.prepareStatement("SELECT * FROM users ORDER BY created_at DESC");ResultSet r=s.executeQuery()){while(r.next())x.add(map(r));}return x;}
 public void setActive(long id,boolean active)throws SQLException {try(Connection c=Database.connection();PreparedStatement s=c.prepareStatement("UPDATE users SET active=? WHERE id=?")){s.setBoolean(1,active);s.setLong(2,id);if(s.executeUpdate()!=1)throw new SQLException("User not found");}}
 private User map(ResultSet r)throws SQLException{return new User(r.getLong("id"),r.getString("full_name"),r.getString("email"),r.getString("password_hash"),Role.valueOf(r.getString("role")),r.getString("phone"),r.getBoolean("active"));}
}
